export function renderTasks(team) {
    const seats = team.seats.filter((s) => !s.disabled);
    const tasks = seats.map((s) => ({
        label: s.label,
        type: "process",
        command: "otterpack",
        args: ["up", s.id],
        isBackground: true,
        problemMatcher: [],
        icon: { id: s.icon, color: `terminal.${s.color}` },
        presentation: {
            panel: "dedicated",
            reveal: "always",
            focus: false,
            echo: false,
            showReuseMessage: false,
            clear: false,
        },
        runOptions: { runOn: "folderOpen", instanceLimit: 1 },
    }));
    tasks.push({
        label: "Team: open all seats",
        dependsOn: seats.map((s) => s.label),
        dependsOrder: "parallel",
        problemMatcher: [],
    });
    const header = "// Team seats: one terminal per seat, generated by otterpack sync from .otterpack/team.yaml.\n" +
        "// Each task attaches to (or restores) its tmux session via `otterpack up`. Don't edit by hand.\n";
    return header + JSON.stringify({ version: "2.0.0", tasks }, null, 2) + "\n";
}
